def convex_fill(g,bg):
    H,W=len(g),len(g[0])
    pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    def cross(a,b,q): return (b[0]-a[0])*(q[1]-a[1])-(b[1]-a[1])*(q[0]-a[0])
    lo=[]
    for p in sorted(pts):
        while len(lo)>=2 and cross(*lo[-2],*lo[-1],p)<=0: lo.pop()
        lo.append(p)
    hi=[]
    for p in reversed(sorted(pts)):
        while len(hi)>=2 and cross(*hi[-2],*hi[-1],p)<=0: hi.pop()
        hi.append(p)
    hull=set(lo[:-1]+hi[:-1])
    res=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c]==bg:
                ok=True
                for i in range(len(hull)):
                    a=hull[i]; b=hull[(i+1)%len(hull)]
                    if cross(a,b,(r,c))<0: ok=False; break
                if ok: res[r][c]=4
    return res
